@EnabledIfEnvironmentVariable(named="MICROFINANCE_RECORDING_TEST_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/microfinance_recording_test")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class GroupSharedWriteOffPostgresTest {
    final GroupSharedLoanPostgresTest s=new GroupSharedLoanPostgresTest();final LoanRecordingPostgresTest f=s.f;
    GroupSharedLoanService hook;LoanAdjustmentRepository posting;GroupMemberStatementService statements;
    @BeforeAll void start(){s.s.s.g.start(Config.class);s.s.agreements=f.context.getBean(GroupSharedAgreementService.class);s.shared=f.context.getBean(GroupSharedLoanService.class);hook=AopTestUtils.getUltimateTargetObject(s.shared);posting=AopTestUtils.getUltimateTargetObject(f.context.getBean(LoanAdjustmentRepository.class));statements=f.context.getBean(GroupMemberStatementService.class);}
    @AfterAll void stop(){s.stop();}
    @BeforeEach void setup(){reset(hook,posting);s.setup();f.service.disburse(f.actor,s.funding());}
    UUID request(){var c=f.adjustments().context(f.actor,s.loan);f.provide(s.loan,c.outstanding().toPlainString());return f.adjustments().request(f.actor,f.adjustment(s.loan,"WRITE_OFF"));}
    UUID writeOff(){var id=request();f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),true,"Synthetic independent shared write-off");return id;}
    @Test void partialLoanWriteOffPartitionsOneBookEntryAndNeverPaysMemberDebt()throws Exception{
        f.service.repay(f.actor,s.payment("120.00"));UUID id=writeOff();var rows=s.shared.balances(f.actor,s.loan);assertThat(rows.getFirst().writtenOff()).isEqualByComparingTo("108.64");assertThat(rows.getLast().writtenOff()).isEqualByComparingTo("771.37");assertThat(rows).allSatisfy(r->assertThat(r.known()).isTrue());assertThat(rows.stream().map(r->r.remainingPrincipal()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("880.01");assertThat(f.adjustments().context(f.actor,s.loan).bookPrincipal()).isZero();assertThat(s.count("gl_journal")).isEqualTo(4);assertThat(s.count("loan_repayment_transactions")).isEqualTo(1);assertThat(s.count("lending_group_shared_adjustment")).isEqualTo(2);
        var own=statements.client(s.s.client,s.s.cycle,null,null,0,0,true);assertThat(own.source().member().remainingPrincipal()).isEqualByComparingTo("108.64");assertThat(own.source().member().writtenOff()).isEqualByComparingTo("108.64");assertThat(own.source().maximumLiability()).isEqualByComparingTo("110.81");assertThat(own.source().status()).isEqualTo("WRITTEN_OFF");assertThat(own.credits()).anySatisfy(r->{assertThat(r.kind()).isEqualTo("WRITE_OFF");assertThat(r.amount()).isZero();assertThat(r.writtenOff()).isEqualByComparingTo("108.64");assertThat(r.number()).startsWith("A-");});assertThatThrownBy(()->f.service.repay(f.actor,s.payment("1.00"))).hasMessage("repayment.error.state");Files.writeString(Path.of("target/shared-writeoff-fixture.json"),"{\"institution\":\""+f.institution+"\",\"client\":\""+f.client+"\",\"actor\":\""+f.actor.getMemberId()+"\",\"cycle\":\""+s.s.cycle+"\",\"loan\":\""+s.loan+"\",\"adjustment\":\""+id+"\"}");
    }
    @Test void restorationCopiesTheOriginalAllocationAndRecoveryStillNeedsActualCash(){
        UUID original=writeOff();var maker=f.operator("B1");var back=f.adjustments().request(maker,f.adjustment(s.loan,"WRITE_BACK"));var key=UUID.randomUUID();f.adjustments().decide(f.actor,back,key,true,"Synthetic independent book restoration");assertThat(f.adjustments().decide(f.actor,back,key,true,"Synthetic independent book restoration")).isEqualTo(back);assertThat(f.adjustments().view(f.actor,back).reversesJournalId()).isEqualTo(f.adjustments().view(f.actor,original).journalId());assertThat(s.shared.balances(f.actor,s.loan)).allSatisfy(r->{assertThat(r.writtenOff()).isZero();assertThat(r.remainingPrincipal()).isEqualByComparingTo(r.principal());});assertThat(s.count("lending_group_shared_adjustment")).isEqualTo(4);assertThat(s.count("loan_repayment_transactions")).isZero();assertThat(f.adjustments().context(f.actor,s.loan).bookPrincipal()).isEqualByComparingTo("1000.01");assertThat(f.adjustments().context(f.actor,s.loan).status()).isEqualTo("DEFAULTED");var own=statements.client(s.s.client,s.s.cycle,null,null,0,0,false);assertThat(own.credits()).hasSize(2).allSatisfy(r->assertThat(r.amount()).isZero()).anySatisfy(r->assertThat(r.reverses()).startsWith("A-")).anySatisfy(r->assertThat(r.reversedBy()).startsWith("A-"));f.service.repay(f.actor,s.payment("5.00"));assertThat(s.shared.balances(f.actor,s.loan).stream().map(r->r.remainingPrincipal()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("995.01");
    }
    @Test void pendingAndRejectedDecisionsNeverCreateAccountingAllocations(){var id=request();assertThat(s.count("lending_group_shared_adjustment")).isZero();f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),false,"Synthetic rejected write-off");assertThat(s.count("lending_group_shared_adjustment")).isZero();assertThat(f.adjustments().benefits(f.actor,id)).isEmpty();assertThat(f.adjustments().context(f.actor,s.loan).status()).isEqualTo("DISBURSED");assertThat(s.count("gl_journal")).isEqualTo(2);}
    @Test void currentGroupClaimsScopeAndExportsRemainMandatory(){
        var id=request();var reviewer=f.operator("B1");var claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.GROUP_LENDING_POST);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(reviewer.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThat(f.adjustments().canDecide(reviewer,id)).isFalse();assertThatThrownBy(()->f.adjustments().decide(reviewer,id,UUID.randomUUID(),true,"Synthetic revoked posting permission")).isInstanceOf(AccessDeniedException.class);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(reviewer.getMemberId()),anyCollection(),anyBoolean())).thenReturn(EnumSet.allOf(UserClaim.class));var key=UUID.randomUUID();f.adjustments().decide(reviewer,id,key,true,"Synthetic valid review");claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.GROUP_LENDING_POST);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(reviewer.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThatThrownBy(()->f.adjustments().decide(reviewer,id,key,true,"Synthetic valid review")).isInstanceOf(AccessDeniedException.class);
        claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.GROUP_LENDING_EXPORT);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(f.actor.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThat(f.adjustments().canExport(f.actor,id)).isFalse();assertThatThrownBy(()->f.adjustments().export(f.actor,id)).isInstanceOf(AccessDeniedException.class);claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.GROUP_LENDING_VIEW);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(f.actor.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThatThrownBy(()->f.adjustments().view(f.actor,id)).isInstanceOf(AccessDeniedException.class);assertThat(f.adjustments().list(f.actor,"","",0,"date","desc").rows()).isEmpty();assertThat(f.adjustments().choices(f.actor,"loans","",0)).isEmpty();assertThatThrownBy(()->f.adjustments().view(f.operator("B2"),id)).isInstanceOf(AccessDeniedException.class);
    }
    @Test void lateAuditFailureRollsBackDecisionJournalStatusAndMemberEvidence(){var id=request();doThrow(new IllegalStateException("Synthetic accounting audit failure")).when(f.context.getBean(AuditService.class)).logEvent(eq("ACCOUNTING_LOAN_ADJUSTMENT"),eq(id),eq("LOAN_ADJUSTMENT_APPROVED"),any(),any(),any(),any(),any(),any(),any(),any());assertThatThrownBy(()->f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),true,"Synthetic late audit rollback")).hasMessage("Synthetic accounting audit failure");assertThat(f.adjustments().view(f.actor,id).state()).isEqualTo("PENDING");assertThat(f.adjustments().context(f.actor,s.loan).status()).isEqualTo("DISBURSED");assertThat(s.count("lending_group_shared_adjustment")).isZero();assertThat(s.count("gl_journal")).isEqualTo(2);}
    @Test void databaseRejectsMissingOrIncorrectMemberAccountingEvidence(){
        var id=request();doNothing().when(hook).accounting(any(),any(),any(),any(),any(),any());assertThatThrownBy(()->f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),true,"Synthetic omitted member evidence")).isInstanceOf(DataAccessException.class).hasStackTraceContaining("Shared accounting adjustment requires complete member attribution");assertThat(f.adjustments().view(f.actor,id).state()).isEqualTo("PENDING");reset(hook);doAnswer(inv->{var source=inv.getArgument(2,UUID.class);f.context.getBean(GroupSharedLoanRepository.class).accounting(f.actor,s.loan,List.of(new AccountingAllocation(source,f.client,new BigDecimal("123.46"),null),new AccountingAllocation(source,s.s.s.g.second,new BigDecimal("876.55"),null)));return null;}).when(hook).accounting(any(),any(),any(),any(),any(),any());assertThatThrownBy(()->f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),true,"Synthetic incorrect personal cents")).isInstanceOf(DataAccessException.class).hasStackTraceContaining("Shared write-off must partition the remaining principal exactly");assertThat(s.count("lending_group_shared_adjustment")).isZero();assertThat(s.count("gl_journal")).isEqualTo(2);
    }
    @Test void accountingEvidenceIsImmutableAndCannotBeAttachedToAnOldDecision(){var id=writeOff();assertThatThrownBy(()->f.jdbc.update("update lending_group_shared_adjustment set amount=0 where request_id=?",id)).isInstanceOf(DataAccessException.class).hasMessageContaining("append-only");assertThatThrownBy(()->f.jdbc.update("delete from lending_group_shared_adjustment where request_id=?",id)).isInstanceOf(DataAccessException.class).hasMessageContaining("append-only");assertThatThrownBy(()->f.jdbc.update("insert into lending_group_shared_adjustment select * from lending_group_shared_adjustment where request_id=? limit 1",id)).isInstanceOf(DataAccessException.class).hasMessageContaining("newly posted scoped decision");}
    @Test void approvedWriteOffAndPersonalDocumentsRetainDifferentFinancialMeanings()throws Exception{
        var id=writeOff();var messages=f.context.getBean(org.springframework.context.MessageSource.class);var renderer=new com.sacco.mvp.accounting.loans.service.LoanRecordingPdfService(new ReportExportLimiter(1));var controller=new com.sacco.mvp.accounting.adjustments.controller.LoanAdjustmentController(f.adjustments(),f.context.getBean(ApplicationClock.class),renderer,messages);var personal=new GroupMemberStatementPdf(renderer,messages);for(var locale:List.of(Locale.ENGLISH,Locale.forLanguageTag("sw"))){var request=new org.springframework.mock.web.MockHttpServletRequest("GET","/finance/loan-adjustments/"+id+"/pdf");var response=controller.export(f.actor,id,locale,request);try(var pdf=Loader.loadPDF(response.getBody())){assertThat(new PDFTextStripper().getText(pdf)).contains("123.45","876.56");}Files.write(Path.of("target/shared-writeoff-staff-"+locale.getLanguage()+".pdf"),response.getBody());var own=statements.client(s.s.client,s.s.cycle,null,null,0,0,true);assertThat(own.source().member().remainingPrincipal()).isEqualByComparingTo("123.45");byte[] bytes=personal.render(own,locale);try(var pdf=Loader.loadPDF(bytes)){assertThat(new PDFTextStripper().getText(pdf)).contains("123.45","125.91").doesNotContain("876.56","Second synthetic client");}Files.write(Path.of("target/shared-writeoff-client-"+locale.getLanguage()+".pdf"),bytes);}assertThat(s.count("gl_journal")).isEqualTo(3);
    }
    @Test void forcedWriteOffWaiverRaceUsesTheRecordedSourceBeforeTheLedger()throws Exception{
        var id=request();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var backend=new AtomicInteger();doAnswer(inv->{backend.set(f.jdbc.queryForObject("select pg_backend_pid()",Integer.class));entered.countDown();if(!release.await(20,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic release timeout");return inv.callRealMethod();}).when(posting).post(any(),any(),any(),any(),any(),any());var clock=f.context.getBean(ApplicationClock.class);when(clock.today()).thenReturn(LoanRecordingPostgresTest.TODAY.plusDays(1));try(var workers=Executors.newFixedThreadPool(2)){var a=workers.submit(()->f.adjustments().decide(f.operator("B1"),id,UUID.randomUUID(),true,"Synthetic forced write-off race"));assertThat(entered.await(10,TimeUnit.SECONDS)).isTrue();var b=workers.submit(()->f.context.getBean(LoanRepaymentLedgerService.class).waiveInterest(s.loan,f.actor,UUID.randomUUID(),clock.today(),new BigDecimal("0.01"),"Synthetic racing concession",null));try{boolean blocked=false;long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(System.nanoTime()<until){blocked=f.jdbc.queryForObject("select exists(select 1 from pg_stat_activity where ?=any(pg_blocking_pids(pid)))",Boolean.class,backend.get());if(blocked)break;Thread.sleep(20);}assertThat(blocked).isTrue();}finally{release.countDown();}assertThat(a.get(30,TimeUnit.SECONDS)).isEqualTo(id);assertThatThrownBy(()->b.get(30,TimeUnit.SECONDS)).isInstanceOf(ExecutionException.class).hasCauseInstanceOf(IllegalArgumentException.class).hasRootCauseMessage("repayment.error.state");}assertThat(s.count("loan_interest_waiver")).isZero();assertThat(s.count("lending_group_shared_adjustment")).isEqualTo(2);assertThat(f.adjustments().context(f.actor,s.loan).status()).isEqualTo("WRITTEN_OFF");
    }
    @Configuration(proxyBeanMethods=false) @Import(GroupSharedWaiverPostgresTest.Config.class) static class Config {
        @Bean @Primary LoanAdjustmentRepository accountingRepository(JdbcTemplate j){return spy(new LoanAdjustmentRepository(j));}
        @Bean @Primary LoanAdjustmentService guardedAccounting(LoanAdjustmentRepository r,GeneralLedgerService a,ApplicationClock clock,AuditService audit,LoanChargeService charges,GroupSharedLoanService shared,JdbcTemplate j){return new LoanAdjustmentService(r,a,new VoucherRepository(j),clock,audit,charges,shared);}
    }
}
